#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
double theta=0.5,h=1e-5;
auto integral=[&](double parameter){
    int n=2000;double sum=0;
    for(int i=0;i<n;i++){
        double x=(i+0.5)/n;
        sum+=exp(parameter*x)/n;
    }
    return sum;
};
int n=2000;double derivativeInside=0;
for(int i=0;i<n;i++){
    double x=(i+0.5)/n;
    derivativeInside+=x*exp(theta*x)/n;
}
cout<<derivativeInside<<" "<<(integral(theta+h)-integral(theta-h))/(2*h)<<"\n";
return 0;
}

