#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
vector<double>baseline={0.5,0.3,0.2},loss={1,4,10};
double sumWeight=0,squaredWeight=0,ordinaryRisk=0;
for(int i=0;i<3;i++){
    sumWeight+=baseline[i];squaredWeight+=baseline[i]*baseline[i];
    ordinaryRisk+=baseline[i]*loss[i];
}
double effective=sumWeight*sumWeight/squaredWeight,worst=-1e100;
for(int a=0;a<=100;a++)for(int b=0;a+b<=100;b++){
    double q[3]={a/100.0,b/100.0,(100-a-b)/100.0},tv=0,risk=0;
    for(int j=0;j<3;j++){
        tv+=fabs(q[j]-baseline[j])/2;
        risk+=q[j]*loss[j];
    }
    if(tv<=0.1+1e-12)worst=max(worst,risk);
}
cout<<"ESS "<<effective<<" nominal "<<ordinaryRisk<<" worstTV "<<worst<<"\n";
return 0;
}
